# ---------------------------------------------------------------- fin de scenario (fne)
def fnefin_carnet_sortant(monde, aides):
    """Le carnet SORTANT, celui que l'ecran de campagne relit apres la partie.

    `WriteCampaignLogAtGameOver` l'ecrit dans le fichier pointe par
    `campaign_log_last_file` au moment ou la partie se termine. On le relit
    ici : `gagnee`, `scenario` (l'estampille), `cles` (valeurs exactes),
    `cles_presentes` et `cles_absentes`.
    """
    import json, os
    from engine.config import ConfigVariables
    attendu = aides["cas"].get("attendu") or {}
    chemin = ConfigVariables.File('campaign_log_last_file', './campaign_log_last.json').value
    if not os.path.exists(chemin):
        return False, f"aucun carnet sortant ecrit ({chemin})"
    with open(chemin, encoding="utf-8") as f:
        carnet = json.load(f)
    suggestions = carnet.get("suggestions") or {}
    soucis = []
    if "gagnee" in attendu and bool(carnet.get("players_won")) != attendu["gagnee"]:
        soucis.append(f"players_won = {carnet.get('players_won')} (attendu {attendu['gagnee']})")
    if "scenario" in attendu and carnet.get("scenario") != attendu["scenario"]:
        soucis.append(f"estampille = {carnet.get('scenario')!r} (attendu {attendu['scenario']!r})")
    for cle, valeur in (attendu.get("cles") or {}).items():
        if suggestions.get(cle) != valeur:
            soucis.append(f"{cle} = {suggestions.get(cle)!r} (attendu {valeur!r})")
    for cle in attendu.get("cles_presentes") or []:
        if cle not in suggestions:
            soucis.append(f"{cle} manque au carnet sortant")
    for cle in attendu.get("cles_absentes") or []:
        if cle in suggestions:
            soucis.append(f"{cle} = {suggestions[cle]!r} alors qu'il ne devrait pas y etre")
    if soucis:
        return False, " ; ".join(soucis) + f" ; carnet = {suggestions}"
    return True, f"carnet sortant ok : scenario={carnet.get('scenario')} gagnee={carnet.get('players_won')}"

# ---- fin des verificateurs fnefin ----

def etat_attendu(monde, aides):
    attendu = aides["cas"].get("attendu") or {}
    identite = aides["identite"](monde)
    soucis = []

    # ⚠ Seulement quand le cas appelle etat_attendu DIRECTEMENT. Un verificateur
    # dedie (al_etat, yondu…) lit ses propres cles (`fleche_sur`, `bras_sur`,
    # `accroche_a` scalaire) puis delegue le reste ici : lui refuser ses cles a
    # fait rougir 14 cas de Yondu et Alligator Loki a la batterie du 11/09.
    if aides["cas"].get("verifier") == "etat_attendu":
        inconnues = sorted(set(attendu) - CLES_ETAT_ATTENDU)
        if inconnues:
            return False, (f"cle(s) attendu INCONNUE(S) de etat_attendu : {inconnues} "
                           f"(une cle inconnue etait ignoree en silence jusqu'au 11/09/2026)")

    # `pv_max` : [[card_id, n]] -> PV max de la carte en jeu (identite comprise).
    for card_id, valeur in attendu.get("pv_max") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (pv_max)")
        elif getattr(face, "max_health", None) != valeur:
            soucis.append(f"{card_id} a {getattr(face, 'max_health', None)} PV max (attendu {valeur})")

    # `traits_de` : [[card_id, TRAIT]] (repris de face_identite).
    for card_id, trait in attendu.get("traits_de") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (traits_de)")
        elif not face.HasTrait(trait):
            soucis.append(f"{card_id} n'a pas le trait {trait}")

    # `hotes` / `accroche_a` : [[carte, hote]] -> la carte est accrochee (bind_face)
    # exactement a l'hote nomme (repris de ares_hotes).
    for cle in ("hotes", "accroche_a"):
        # `accroche_a` existe aussi en forme SCALAIRE (al_etat : le heros accroche
        # a tel ennemi, ou None) : cette forme est lue par al_etat, pas ici.
        valeur = attendu.get(cle)
        if not isinstance(valeur, list):
            continue
        for paire in valeur:
            if not (isinstance(paire, (list, tuple)) and len(paire) == 2):
                continue
            carte_id, hote_id = paire
            carte = aides["par_id"](monde, carte_id)
            if carte is None:
                soucis.append(f"{carte_id} n'est pas en jeu ({cle})")
                continue
            hote = getattr(carte, "bind_face", None)
            hote_reel = getattr(getattr(hote, "paper", None), "card_id", None)
            if hote_reel != hote_id:
                soucis.append(f"{carte_id} est accrochee a {hote_reel}, attendu {hote_id}")

    # `carte_du_surge` : card_id seme au sommet du deck de rencontre ; le surge
    # doit l'avoir revele, il n'est donc plus dans le deck.
    if attendu.get("carte_du_surge"):
        from game.operate.worlds import Worlds
        semee = attendu["carte_du_surge"]
        deck = [getattr(f.paper, "card_id", None) for f in Worlds.GetEncounterDeckCards(monde)]
        if semee in deck:
            soucis.append(f"{semee} est encore dans le deck de rencontre : le surge n'a rien revele")

    for nom, ecart in (attendu.get("attributs") or {}).items():
        courant = identite.max_health if nom == "health" else getattr(identite, nom)
        base = getattr(identite, IMPRIME[nom])
        if courant != base + ecart:
            soucis.append(f"{nom}={courant} (imprime {base}, attendu {base + ecart})")

    for trait in attendu.get("traits") or []:
        if not identite.HasTrait(trait):
            soucis.append(f"trait {trait} absent de l'identite")

    # AJOUTEE le 05/09/2026 (pack throg). Le pendant negatif de `traits`, sans
    # lequel on ne peut PAS prouver qu'un trait accorde par une carte ne fuit
    # pas sur l'autre face. RECETTES-MOTEUR §3 l'exige pourtant : « tout bonus
    # continu d'identite exige un contre-cas dans l'AUTRE forme » — regle nee
    # du defaut `an002` Sera, trouve en partie reelle par le joueur le
    # 1/9/2026 et JAMAIS par les tests, faute de cette cle.
    for trait in attendu.get("traits_absents") or []:
        if identite.HasTrait(trait):
            soucis.append(f"trait {trait} PRESENT sur l'identite, il ne devrait pas y etre")

    for card_id in attendu.get("en_jeu") or []:
        if aides["par_id"](monde, card_id) is None:
            soucis.append(f"{card_id} n'est pas en jeu")

    for card_id in attendu.get("hors_jeu") or []:
        if aides["par_id"](monde, card_id) is not None:
            soucis.append(f"{card_id} est encore en jeu")

    # `aucune_en_resolution` : AUCUNE carte ne doit rester dans une zone de
    # traitement a la fin du cas. AJOUTEE le 21/09/2026 (signalement Aghenatak).
    # La zone de traitement est un SAS : une carte y transite le temps qu'un
    # effet se resolve. Une carte qui y reste n'est ni en jeu ni en defausse,
    # donc plus rien ne la touche — et le plateau, lui, la montre posee sur la
    # table, ce qui la fait passer pour un soutien. Aucune cle existante ne
    # savait le voir : `hors_jeu` est VRAI pour une carte coincee, et
    # `dans_deck_joueur` ne regarde que le deck.
    if attendu.get("aucune_en_resolution"):
        coincees = []
        zones = [monde.area_processing] + [j.area_processing for j in monde.players]
        for zone in zones:
            for face in zone.GetAll():
                coincees.append(getattr(face.paper, "card_id", "?"))
        if coincees:
            soucis.append(f"carte(s) restee(s) en zone de traitement : {coincees}")

    # Cle `compteurs_identite` (AJOUT 10/09/2026, pack spider_woman_kajislav) :
    # les compteurs portes par L'IDENTITE, quelle que soit sa FACE. `compteurs`
    # designe une carte par son card_id ; or une identite change de card_id en
    # changeant de forme (sw001b -> sw001a), et le stock, lui, ne bouge pas. Un
    # temoin dont le pilote fait basculer la forme rendait donc « sw001b
    # introuvable en jeu » au lieu de mesurer ce qu'on lui demandait.
    for compteur, valeur in attendu.get("compteurs_identite") or []:
        n = identite.CastTo(aides["CanPlaceCounter"]).GetCounters(compteur)
        if n != valeur:
            soucis.append(f"identite.{compteur}={n} (attendu {valeur})")

    for card_id, compteur, valeur in attendu.get("compteurs") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (compteurs)")
            continue
        n = face.CastTo(aides["CanPlaceCounter"]).GetCounters(compteur)
        if n != valeur:
            soucis.append(f"{card_id}.{compteur}={n} (attendu {valeur})")

    # Jetons et compteurs sont deux stocks distincts : la menace posee sur une
    # carte joueur (Beat Cop, Private Investigator) est un JETON 'threat'.
    for card_id, jeton, valeur in attendu.get("jetons") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (jetons)")
            continue
        n = face.CastTo(aides["CanPlaceToken"]).GetTokens(jeton)
        if n != valeur:
            soucis.append(f"{card_id}.{jeton}={n} jeton(s) (attendu {valeur})")

    for compteur, mini in attendu.get("compteurs_total") or []:
        total = 0
        for objet in monde.object_manager.card_dict.values():
            face = objet.face
            if face is None or not face.IsInPlay():
                continue
            if isinstance(face, aides["CanPlaceCounter"]):
                total += face.GetCounters(compteur)
        if total < mini:
            soucis.append(f"total des compteurs « {compteur} » en jeu = {total} "
                          f"(attendu au moins {mini})")

    # `menace_min` plutot que `menace` des que la valeur exacte depend du
    # tirage : la manigance d'un vilain vaut son SCH plus ses icones de boost,
    # qui changent avec le nombre de joueurs.
    for card_id, mini in attendu.get("menace_min") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (menace)")
        elif face.threat < mini:
            soucis.append(f"menace sur {card_id} = {face.threat} (attendu au moins {mini})")

    for card_id, valeur in attendu.get("menace") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (menace)")
            continue
        if face.threat != valeur:
            soucis.append(f"menace sur {card_id} = {face.threat} (attendu {valeur})")

    for card_id, nom, ecart in attendu.get("attributs_carte") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (attribut {nom})")
            continue
        courant = face.max_health if nom == "health" else getattr(face, nom)
        base = getattr(face, IMPRIME[nom])
        if courant != base + ecart:
            soucis.append(f"{card_id}.{nom}={courant} "
                          f"(imprime {base}, attendu {base + ecart})")

    for card_id, valeur in attendu.get("degats") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (degats)")
        elif face.max_health - face.health != valeur:
            soucis.append(f"degats sur {card_id} = {face.max_health - face.health} "
                          f"(attendu {valeur})")

    for card_id, mini in attendu.get("degats_min") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (degats_min)")
        elif face.max_health - face.health < mini:
            soucis.append(f"degats sur {card_id} = {face.max_health - face.health} "
                          f"(attendu au moins {mini})")

    if "degats_identite" in attendu:
        subis = identite.max_health - identite.health
        if subis != attendu["degats_identite"]:
            soucis.append(f"degats sur l'identite = {subis} "
                          f"(attendu {attendu['degats_identite']})")

    # ⚠ CORRECTIF DU 05/09/2026 (pack throg). `degats_identite_min` etait
    # ecrite dans des cas depuis longtemps, mais n'existait QUE dans
    # `al_frogjolnir_sur_throg`, une verification propre au pack
    # alligator_loki. Tout cas qui l'employait avec `"verifier":
    # "etat_attendu"` voyait donc sa cle SILENCIEUSEMENT IGNOREE : une
    # assertion qui ne mesure rien, et un cas vert qui ne prouve rien.
    # Trouve parce que le cas Perforation de `tg013` restait vert sous
    # substitution alors que la sonde mesurait 3 degats avec le module et
    # 0 sans, trois fois de suite. Meme famille que les quatre facons de
    # mesurer RIEN du §7bis de RECETTES-MOTEUR.
    if "degats_identite_min" in attendu:
        subis = identite.max_health - identite.health
        if subis < attendu["degats_identite_min"]:
            soucis.append(f"degats sur l'identite = {subis} "
                          f"(attendu au moins {attendu['degats_identite_min']})")

    # Les ICONES en jeu (Hazard, Amplify, Acceleration, Crisis). Ajoute le
    # 09/09/2026 pour vz031 First Contact : ces mots-cles sont des BASES
    # AUTOMATIQUES lues dans `desc`, sans script, et aucune cle existante ne
    # pouvait dire s'ils etaient reellement PORTES. `attributs_carte` compare la
    # valeur courante a la valeur IMPRIMEE : avec un desc vide les deux valent
    # zero et le cas passe au vert sans rien prouver.
    for nom_icone, attendu_n in (attendu.get("icones") or []):
        from game.operate.worlds import Worlds
        n = Worlds.GetIconsNum(monde.players[0].GetIdentity().card.game_area, [nom_icone])
        if n != attendu_n:
            detail = []
            for f in Worlds.GetOnFieldCards(monde.players[0].GetIdentity().card.game_area):
                detail.append(f"{getattr(f.paper,'card_id','?')}:"
                              f"imprime={getattr(f,'printed_hazard','-')}"
                              f",courant={getattr(f,'hazard','-')}")
            soucis.append(f"icones {nom_icone} en jeu = {n} (attendu {attendu_n}) "
                          f"[{' '.join(detail)}]")

    # Cle `icones_boost` (AJOUT 09/09/2026, pack iron_patriot) : le nombre
    # d'icones de [boost] d'une carte EN JEU, lu par le meme chemin que le
    # moteur (`CountBoostIconsInternal`, has_boost_icon.py:31) — donc en voyant
    # les modificateurs. C'est la SEULE grandeur que `ip008` Director of
    # Security modifie, et aucune cle existante ne la regarde : `icones` compte
    # les icones de MANIGANCE (crise, acceleration, amplification, danger), pas
    # celles de boost.
    for card_id, attendu_n in attendu.get("icones_boost") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (icones_boost)")
            continue
        n = face.CountBoostIconsInternal()
        if n != attendu_n:
            soucis.append(f"{card_id} a {n} icone(s) de boost (attendu {attendu_n})")

    # Cle `boosts_sur` (AJOUT 20/10/2026, backlog 13, Zeus) : [[card_id, n]] ->
    # nombre de cartes de boost que la carte `card_id` a RECUES depuis le debut
    # du cas, toutes activations confondues. Le compteur est pose par
    # `executer_un_cas` sur `Boostable.GiveBoostCard` (voir le commentaire
    # la-bas). Les cartes de boost sont defaussees en fin d'activation : aucune
    # autre cle ne peut voir leur nombre.
    if attendu.get("boosts_sur"):
        from game.card.face.component.boostable import Boostable
        recus = getattr(Boostable, "_harnais_boosts_recus", None)
        if recus is None:
            soucis.append("compteur de boosts absent (boosts_sur) : le crochet de "
                          "executer_un_cas n'est pas pose")
        else:
            for card_id, attendu_n in attendu["boosts_sur"]:
                n = recus.get(card_id, 0)
                if n != attendu_n:
                    soucis.append(f"{card_id} a recu {n} carte(s) de boost "
                                  f"(attendu {attendu_n} ; compteur = {dict(recus)})")

    if attendu.get("dans_deck_rencontre"):
        from game.operate.worlds import Worlds
        ids = {getattr(f.paper, "card_id", None)
               for f in Worlds.GetEncounterDeckCards(monde)}
        for card_id in attendu["dans_deck_rencontre"]:
            if card_id not in ids:
                soucis.append(f"{card_id} absent du deck Rencontre")

    if "forme" in attendu:
        courante = "Hero" if monde.players[0].IsHero() else "AlterEgo"
        if courante != attendu["forme"]:
            soucis.append(f"forme {courante} (attendu {attendu['forme']})")

    # `face_identite` : card_id EXACT de la face d'identite en jeu. AJOUT du
    # 25/09/2026 (pack conan, identite a cinq faces) : `forme` ne distingue que
    # Hero/AlterEgo, donc Conan the Thief et King Conan passaient pour pareils.
    if "face_identite" in attendu:
        reelle = getattr(getattr(identite, "paper", None), "card_id", None)
        if reelle != attendu["face_identite"]:
            soucis.append(f"face d'identite {reelle} (attendue {attendu['face_identite']})")

    for trait, mini in attendu.get("en_jeu_trait") or []:
        n = 0
        for objet in monde.object_manager.card_dict.values():
            face = objet.face
            if face is not None and face.IsInPlay() and face.HasTrait(trait):
                n += 1
        if n < mini:
            soucis.append(f"{n} carte(s) {trait} en jeu (attendu au moins {mini})")

    for card_id in attendu.get("exhausted") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (inclinaison)")
        elif not face.IsExhaust():
            soucis.append(f"{card_id} n'est pas incline")

    for card_id in attendu.get("pret") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (inclinaison)")
        elif face.IsExhaust():
            soucis.append(f"{card_id} est incline alors qu'il devrait etre pret")

    for card_id, statut in attendu.get("statuts") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (statut {statut})")
        elif not face.CastTo(aides["CanStatus"]).HasStatus(statut):
            soucis.append(f"{card_id} ne porte pas le statut {statut}")

    # Cle `statuts_absents` : l'inverse de `statuts`. Indispensable des qu'un cas
    # prouve qu'un statut a ete CONSOMME — c'est la moitie invisible des labels
    # 'attack'/'thwart', qui n'ont d'autre effet observable que de livrer la
    # capacite a Sonne et Desoriente (`cards/pack/status/`).
    for card_id, statut in attendu.get("statuts_absents") or []:
        face = aides["par_id"](monde, card_id)
        if face is None:
            soucis.append(f"{card_id} introuvable en jeu (statut {statut})")
        elif face.CastTo(aides["CanStatus"]).HasStatus(statut):
            soucis.append(f"{card_id} porte ENCORE le statut {statut}")

    # `defausse` prouve qu'un evenement a bien ete JOUE : un evenement encore en
    # main n'est ni « en jeu » ni dans la defausse, donc `hors_jeu` ne le voit pas.
    for card_id in attendu.get("defausse") or []:
        cartes = [getattr(f.paper, "card_id", None)
                  for f in monde.players[0].discard_pile.Get()]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas dans la defausse du joueur "
                          f"(defausse = {cartes})")

    # Cle `defausse_dessus` (30/09/2026, signalement Yarro n30) : le card_id de la
    # carte du DESSUS de la defausse du joueur. `defausse` ne voit que
    # l'appartenance, or l'action de Neena Thurman echange avec la carte du dessus.
    if "defausse_dessus" in attendu:
        dessus = monde.players[0].discard_pile.GetTop()
        vu = getattr(getattr(dessus, "paper", None), "card_id", None)
        if vu != attendu["defausse_dessus"]:
            soucis.append(f"dessus de la defausse = {vu}, attendu {attendu['defausse_dessus']}")

    # Cle `defausse_rencontre` (AJOUT 10/09/2026, pack iron_patriot) : le
    # pendant de `defausse` pour la pile de RENCONTRE. Sans elle, la regle de
    # l'insert « un sbire REGISTERED non recrute part en defausse de rencontre »
    # n'etait prouvable que par la NEGATIVE (« il n'est plus en jeu »), ce qui
    # laissait passer le cas ou il finissait dans la defausse du JOUEUR — ce
    # qu'il faisait vraiment.
    for card_id in attendu.get("defausse_rencontre") or []:
        # ⚠ On lit les piles A LA SOURCE : le vilain actif en a une, et le
        # scenario la sienne (villain.py:144, scenario.py:19). `Worlds` expose
        # bien un raccourci, mais il exige un `Effect`, que la verification
        # n'a pas.
        # CORRECTIF 18/09/2026 (pack fne) : `monde.villains` n'existe pas, et
        # la pile du scenario n'est pas celle ou le vilain defausse (Power
        # Struggle a defausse 2 cartes « vers EncounterDiscardPile<3> » et la
        # cle lisait une pile vide). On passe par `Worlds`, comme
        # `Puzzle.FindOrCreateFace`, qui accepte un World.
        from game.operate.worlds import Worlds
        piles = [monde.GetScenario().encounter_discard_pile]
        for villain in getattr(monde, "villains", []) or []:
            pile = getattr(villain, "encounter_discard_pile", None)
            if pile is not None:
                piles.append(pile)
        cartes = [getattr(f.paper, "card_id", None)
                  for pile in piles for f in pile.GetAll()]
        cartes += [getattr(f.paper, "card_id", None)
                   for f in Worlds.GetEncounterDiscardPileCards(monde)]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas dans la defausse de rencontre "
                          f"(defausse = {cartes})")

    # `taille_deck_joueur` (11/09/2026, pack hellcat) : taille du deck du joueur.
    if "taille_deck_joueur" in attendu:
        n = len(list(monde.players[0].player_deck.Get(True)))
        if n != attendu["taille_deck_joueur"]:
            soucis.append(f"deck du joueur = {n} carte(s) (attendu {attendu['taille_deck_joueur']})")

    if "taille_main" in attendu:
        n = len(list(monde.players[0].hand_cards.Get()))
        if n != attendu["taille_main"]:
            soucis.append(f"main = {n} carte(s) (attendu {attendu['taille_main']})")

    # Cle `dans_deck_joueur` (AJOUT 01/09/2026, pack beast) : le pendant de
    # `dans_deck_rencontre` pour le deck du JOUEUR. Sans elle, aucune capacite
    # qui melange une carte dans le deck n'est prouvable : la carte n'est ni en
    # jeu, ni en main, ni dans la defausse, donc aucune des cles existantes ne
    # la voit. C'est le cas du pool « Discovery » de Beast, que bt001b et bt006
    # font passer du set_aside vers le deck.
    for card_id in attendu.get("dans_deck_joueur") or []:
        cartes = [getattr(f.paper, "card_id", None)
                  for f in monde.players[0].player_deck.GetAll()]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas dans le deck du joueur "
                          f"(deck = {cartes})")

    # Cle `dans_deck_registered` (AJOUT 09/09/2026, pack iron_patriot) : le
    # `additional_deck` du joueur, c'est-a-dire le DECK REGISTERED de Norman
    # Osborn. `mis_de_cote` ne le voit pas — il lit `set_aside_deck`, qui est
    # la DEFAUSSE de ce deck (player.py:100). Sans cette cle, aucune carte qui
    # melange un sbire DANS le deck REGISTERED n'est prouvable : `ip001a`
    # Authoritative Force, `ip006` Victoria Hand et `ip011` Foreboding
    # Influence ne font que cela.
    for card_id in attendu.get("dans_deck_registered") or []:
        cartes = [getattr(f.paper, "card_id", None)
                  for f in monde.players[0].additional_deck.GetAll()]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas dans le deck REGISTERED "
                          f"(deck = {cartes})")

    if "taille_deck_registered" in attendu:
        n = len(list(monde.players[0].additional_deck.Get()))
        if n != attendu["taille_deck_registered"]:
            soucis.append(f"deck REGISTERED = {n} carte(s) "
                          f"(attendu {attendu['taille_deck_registered']})")

    # Cle `mis_de_cote` (AJOUT 01/09/2026, pack beast) : le `set_aside_deck` du
    # joueur, alias de `additional_discard_pile`. Prouve qu'une carte y est
    # ENCORE — ou, en contre-cas, qu'elle en est bien partie.
    # Paquets de pieges (Kraven) : `paquet_pieges` / `defausse_pieges` = taille,
    # `pieges_distribues` = [[rang du joueur, taille]] (paquets DealtTrapN).
    _decks_hs = getattr(monde, "scenario_decks", {}) or {}
    for cle, nom in (("paquet_pieges", "TrapDeck"), ("defausse_pieges", "TrapDeck")):
        if cle in attendu:
            d = _decks_hs.get(nom)
            n = None if d is None else (d.deck.GetSize() if cle == "paquet_pieges" else d.discard_pile.GetSize())
            if n != attendu[cle]:
                soucis.append(f"{cle} = {n} (attendu {attendu[cle]})")
    for rang, taille in attendu.get("pieges_distribues") or []:
        d = _decks_hs.get(f"DealtTrap{rang}")
        n = None if d is None else d.deck.GetSize()
        if n != taille:
            soucis.append(f"pieges distribues au joueur {rang} = {n} (attendu {taille})")
    for card_id in attendu.get("mis_de_cote_scenario") or []:
        cartes = [getattr(f.paper, "card_id", None) for f in monde.aside_deck.GetAll()]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas mis de cote par le scenario (aside = {cartes})")
    for card_id in attendu.get("mis_de_cote") or []:
        cartes = [getattr(f.paper, "card_id", None)
                  for f in monde.players[0].set_aside_deck.GetAll()]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas mis de cote "
                          f"(set_aside = {cartes})")

    if "taille_mis_de_cote" in attendu:
        n = len(list(monde.players[0].set_aside_deck.Get()))
        if n != attendu["taille_mis_de_cote"]:
            soucis.append(f"set_aside = {n} carte(s) "
                          f"(attendu {attendu['taille_mis_de_cote']})")

    for card_id in attendu.get("en_main") or []:
        cartes = [getattr(f.paper, "card_id", None)
                  for f in monde.players[0].hand_cards.GetAll()]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas en main (main = {cartes})")

    for card_id in attendu.get("absent_main") or []:
        cartes = [getattr(f.paper, "card_id", None)
                  for f in monde.players[0].hand_cards.GetAll()]
        if card_id in cartes:
            soucis.append(f"{card_id} est en main alors qu'il ne devrait pas (main = {cartes})")

    # La RESERVE du pack brawn : zone hors-jeu de 3 cartes au plus, dont les
    # cartes restent jouables et depensables. Sans cette cle, aucun cas ne peut
    # prouver qu'une carte y est bien arrivee.
    for card_id in attendu.get("en_reserve") or []:
        cartes = [getattr(f.paper, "card_id", None)
                  for f in monde.players[0].reserve.GetAll()]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas en reserve (reserve = {cartes})")

    if "taille_reserve" in attendu:
        n = len(list(monde.players[0].reserve.Get()))
        if n != attendu["taille_reserve"]:
            soucis.append(f"reserve = {n} carte(s) (attendu {attendu['taille_reserve']})")

    # La RISING TIDE AREA du pack wave (AJOUT 22/09/2026) : meme famille que
    # la Reserve ci-dessus, zone hors-jeu propre au joueur. `en_rising_tide`
    # verifie juste la PRESENCE (independamment de l'etat face visible/
    # cachee) ; `rising_tide_face_visible` verifie en plus l'etat de face
    # d'un id donne -- necessaire pour prouver que Champion Swimmer/Storm
    # Surge/Tide Wall posent bien FACE VISIBLE (l'insert l'exige), et que les
    # cartes retournees par les evenements signature repassent bien face
    # CACHEE.
    for card_id in attendu.get("en_rising_tide") or []:
        cartes = [getattr(f.paper, "card_id", None)
                  for f in monde.players[0].rising_tide.GetAll(False)]
        if card_id not in cartes:
            soucis.append(f"{card_id} n'est pas dans la Rising Tide area (zone = {cartes})")

    if "taille_rising_tide" in attendu:
        n = len(list(monde.players[0].rising_tide.GetAll(False)))
        if n != attendu["taille_rising_tide"]:
            soucis.append(f"rising_tide = {n} carte(s) (attendu {attendu['taille_rising_tide']})")

    for card_id, face_visible_attendu in (attendu.get("rising_tide_face_visible") or []):
        trouvee = None
        for f in monde.players[0].rising_tide.GetAll(False):
            if getattr(f.paper, "card_id", None) == card_id:
                trouvee = f
                break
        if trouvee is None:
            soucis.append(f"{card_id} n'est pas dans la Rising Tide area (face visible non verifiable)")
        elif trouvee.IsFaceUp() != face_visible_attendu:
            soucis.append(f"{card_id} en Rising Tide area : face visible = "
                          f"{trouvee.IsFaceUp()} (attendu {face_visible_attendu})")

    # Cles `pose_sous` et `taille_pose_sous` (AJOUT 01/09/2026, web_of_deceit) :
    # la zone des cartes POSEES sous une autre (`GetPlacedCardArea`). Sans
    # elles, aucune capacite qui range une carte sous une autre n'est prouvable :
    # la carte n'est ni en jeu, ni en main, ni dans la defausse, ni dans un deck.
    # C'est le cas de wd084 Highway Robbery, qui prend une carte au hasard dans
    # chaque main et la pose face cachee sous elle.
    # ⚠ `Get(True)` et non `Get()` : le drapeau demande aussi les cartes FACE
    # CACHEE, et c'est precisement ainsi que wd084 les pose.
    for hote, card_id in attendu.get("attaches") or []:
        face = aides["par_id"](monde, hote)
        if face is None:
            soucis.append(f"{hote} introuvable en jeu (attaches)")
            continue
        portees = [getattr(f.paper, "card_id", None) for f in face.GetInventoryDeck().GetAll()]
        if card_id not in portees:
            soucis.append(f"{card_id} n'est pas attache a {hote} (attaches = {portees})")
    for hote, card_id in attendu.get("pose_sous") or []:
        face = aides["par_id"](monde, hote)
        if face is None:
            soucis.append(f"{hote} introuvable en jeu (pose_sous)")
            continue
        posees = [getattr(f.paper, "card_id", None)
                  for f in face.GetPlacedCardArea().Get(True)]
        if card_id not in posees:
            soucis.append(f"{card_id} n'est pas pose sous {hote} (pose = {posees})")

    for hote, valeur in attendu.get("taille_attaches") or []:
        face = aides["par_id"](monde, hote)
        if face is None:
            soucis.append(f"{hote} introuvable en jeu (taille_attaches)")
            continue
        n = len(list(face.GetInventoryDeck().GetAll()))
        if n != valeur:
            soucis.append(f"{n} carte(s) attachee(s) a {hote} (attendu {valeur})")

    for hote, valeur in attendu.get("taille_pose_sous") or []:
        face = aides["par_id"](monde, hote)
        if face is None:
            soucis.append(f"{hote} introuvable en jeu (taille_pose_sous)")
            continue
        n = len(list(face.GetPlacedCardArea().Get(True)))
        if n != valeur:
            soucis.append(f"{n} carte(s) posee(s) sous {hote} (attendu {valeur})")

    if "defausse_joueur" in attendu:
        n = len(list(monde.players[0].discard_pile.Get()))
        if n != attendu["defausse_joueur"]:
            soucis.append(f"defausse du joueur = {n} carte(s) "
                          f"(attendu {attendu['defausse_joueur']})")

    if soucis:
        return False, " ; ".join(soucis)
    return True, "etat conforme"

