def okoye_midnight_angel_armor_stats(monde, aides):
    """ok012/ok013 : +2 PV, trait AERIAL, sur le personnage DORA MILAJE attache."""
    dora = aides["par_id"](monde, "ok017")
    if dora is None:
        return False, "ok017 (Dora Milaje) introuvable en jeu"
